/**
 * Creates the labels of several shipments, and returns the shipments in the same order.
 * The carrier accepts one label request at a time per account, so the requests go out one after
 * the other; the first failure stops the rest from being sent.
 */
export async function createLabels(shipments, transport) {
  const labelled = [];
  for (const shipment of shipments) {
    labelled.push(await createLabel(shipment, transport));
  }
  return labelled;
}

